  "inlineSchema": "// prisma/schema.prisma\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n  url      = \"file:./dev.db\"\n}\n\n// Room - represents a conversation space (e.g., \"Family\")\nmodel Room {\n  id          String   @id @default(uuid())\n  name        String\n  type        String   @default(\"family\") // family, friends, colleagues\n  description String?\n  context     String? // Room-specific context for AI\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  // External chat platform mapping (e.g., Feishu group ID)\n  externalChatId String? @unique\n\n  agents      Agent[]\n  messages    Message[]\n  discussions Discussion[]\n\n  // OpenClaw session tracking\n  openclawSessionId String?\n  sessionMaxAge     Int       @default(86400) // 24 hours in seconds\n  sessionCreatedAt  DateTime?\n}\n\n// Agent - an AI persona in a room\nmodel Agent {\n  id     String @id @default(uuid())\n  roomId String\n  room   Room   @relation(fields: [roomId], references: [id], onDelete: Cascade)\n\n  name   String\n  role   String // e.g., \"father\", \"mother\", \"child\", \"grandparent\"\n  avatar String? // URL or emoji\n\n  // Personality traits (0-100)\n  talkativeness Int @default(50)\n  empathy       Int @default(50)\n  curiosity     Int @default(50)\n\n  // System prompt override (optional)\n  systemPrompt String?\n\n  // Status\n  isActive      Boolean @default(true)\n  responseDelay Int     @default(1000) // ms, for realism\n\n  // Relationships to other agents\n  relationshipsAsA Relationship[] @relation(\"AgentARelationships\")\n  relationshipsAsB Relationship[] @relation(\"AgentBRelationships\")\n\n  // Messages from this agent\n  messages Message[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([roomId, name])\n}\n\n// Relationship - defines how agents relate to each other\nmodel Relationship {\n  id       String @id @default(uuid())\n  agentAId String\n  agentBId String\n  agentA   Agent  @relation(\"AgentARelationships\", fields: [agentAId], references: [id], onDelete: Cascade)\n  agentB   Agent  @relation(\"AgentBRelationships\", fields: [agentBId], references: [id], onDelete: Cascade)\n\n  type     String // parent-of, child-of, spouse, sibling, friend, colleague\n  strength Int     @default(50) // 0-100\n  context  String? // Additional context about the relationship\n\n  createdAt DateTime @default(now())\n\n  @@unique([agentAId, agentBId])\n}\n\n// Message - conversation history\nmodel Message {\n  id     String @id @default(uuid())\n  roomId String\n  room   Room   @relation(fields: [roomId], references: [id], onDelete: Cascade)\n\n  agentId String? // null if from admin user\n  agent   Agent?  @relation(fields: [agentId], references: [id], onDelete: SetNull)\n\n  role    String // \"user\" or \"assistant\"\n  content String\n\n  // Metadata\n  metadata String? // JSON string for additional data\n\n  createdAt DateTime @default(now())\n\n  @@index([roomId, createdAt])\n}\n\n// Discussion - tracks active topic discussions\nmodel Discussion {\n  id     String @id @default(uuid())\n  roomId String\n  room   Room   @relation(fields: [roomId], references: [id], onDelete: Cascade)\n\n  topic     String\n  heatScore Int    @default(50) // 0-100\n  status    String @default(\"active\") // active, cooling, ended\n\n  // Participants (stored as JSON array of agent IDs)\n  participants String? // JSON array: [\"agent1\", \"agent2\"]\n\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n  endedAt   DateTime?\n\n  @@index([roomId, status])\n}\n",
